      <label class="live">Toposz clustering (core similarity): <input type="range" id="slider-cl" min="0.50" max="1.00" step="0.01" value="${st.cluster}"><span id="cl-val" class="slider-val">${Number(st.cluster).toFixed(2)}</span></label>
      <label class="live-toggle">Group into toposz: <input type="checkbox" id="cmp-group" checked></label>
      <button id="cmp-recompute" class="more-btn cmp-recompute" title="Recompute with the set n-gram / n_out / min-chain / fuzzy / cluster values">↻ Recompute</button>
