/* Collapse formulaic duplicates into one row per toposz.

   Cluster members index into result.pairs, which is the order pairs were
   streamed (the order the engine assigned them) — the same order `all` is in
   here, since the streaming path never re-sorts the array itself. A cluster is
   emitted at the position of its own best-ranked member; its other members are
   rendered inside it and skipped at top level. */
function _cmpGroupHtml(all, clusters, t1, t2) {
  const rank = new Map();
  all.map((_, i) => i)
     .sort((a, b) => all[b].chain_len - all[a].chain_len)
     .forEach((idx, r) => rank.set(idx, r));
  const clusterOf = new Map();
  clusters.forEach((c) => c.members.forEach((m) => clusterOf.set(m, c)));
  const top = [];

content.content:
  const top = [];
  const seen = new Set();
  all.forEach((p, i) => {
    const c = clusterOf.get(i);
    if (!c) { top.push({ key: rank.get(i), html: () => _cmpPairHtml(p, t1, t2) }); return; }
    if (seen.has(c.id)) return;
    seen.add(c.id);
    const members = c.members.slice().sort((a, b) => rank.get(a) - rank.get(b));
    top.push({ key: rank.get(members[0]), html: () => _cmpClusterHtml(c, members, all, t1, t2) });
  });
  top.sort((a, b) => a.key - b.key);
  return top;
}

function _cmpClusterHtml(c, members, all, t1, t2) {
  const best = all[members[0]];
  const refs = members.slice(0, 4).map((m) => all[m].label_i).join(" · ")
    + (members.length > 4 ? " · …" : "");
  const refs2 = members.slice(0, 4).map((m) => all[m].label_j).join(" · ")
    + (members.length > 4 ? " · …" : "");
  const inline = members.slice(0, CMP_CLUSTER_INLINE);
  const rest = members.slice(CMP_CLUSTER_INLINE);
  return `
    <div class="cmp-cluster" data-size="${c.size}">
      <details>
        <summary class="cmp-cluster-head">
          <span class="cmp-cluster-count">${c.size}×</span>
          <span class="cmp-cluster-core">${esc(best.core_text || best.snippet_i || "—")}</span>
          <span class="cmp-cluster-meta">toposz · best chain ${best.chain_len}</span>
        </summary>
        <div class="cmp-cluster-refs">
          <span class="apparatus">${esc(t1)}</span> ${esc(refs)}<br>
          <span class="apparatus">${esc(t2)}</span> ${esc(refs2)}
        </div>
        <div class="cmp-cluster-body">
          ${inline.map((m) => _cmpPairHtml(all[m], t1, t2)).join("")}
          ${rest.length ? `<details class="cmp-cluster-rest">
            <summary>show the remaining ${rest.length} occurrence${rest.length > 1 ? "s" : ""}</summary>
            ${rest.map((m) => _cmpPairHtml(all[m], t1, t2)).join("")}
          </details>` : ""}
        </div>
      </details>
    </div>`;
}

/* Re-render ONLY the pairs container from the accumulated, sorted pairs. */
function renderCmpPairs() {
  const host = document.getElementById("cmp-pairs");
  if (!host || !_cmpLast) return;
  const all = _cmpLast.result.pairs;
  const d = _cmpLast;
  const t1 = (d.work1 && d.work1.title) || "1";
  const t2 = (d.work2 && d.work2.title) || "2";
  const grouping = document.getElementById("cmp-group");
  const grouped = grouping ? grouping.checked : true;
  const clusters = (d.result.clusters || []);

  let items, label;
  if (grouped && clusters.length) {
    items = _cmpGroupHtml(all, clusters, t1, t2);
    label = "toposz";
  } else {
    // Ungrouped: one unit per pair, ranked by chain length (best first) so the
    // two branches agree on what `key` means.
    items = all.map((p, i) => i)
               .sort((a, b) => all[b].chain_len - all[a].chain_len)
               .map((i, rank) => ({ key: rank, html: () => _cmpPairHtml(all[i], t1, t2) }));
    label = "pairs";
  }
  const total = items.length;
  const shown = items.slice(0, CMP_RENDER_CAP);
  host.innerHTML = shown.map((it) => it.html()).join("")
    || '<p class="reader-empty">No matches to show yet…</p>';

  const note = document.getElementById("cmp-note");
  if (note) {
    const unit = grouped && clusters.length
      ? `toposz clusters + singletons` : `${all.length} pairs`;
    note.innerHTML = `Shown: ${shown.length}/${total} ${label} (best chains) · ${unit} — ` +
      `<b>all</b> ${all.length} pairs are in the export (⤓). After a server-side slider: <b>↻ Recompute</b>.`;
  }
  const info = document.querySelector(".cmp-info");
  if (info) info.innerHTML = _cmpInfoHtml();

  host.querySelectorAll(".cmp-hl").forEach((el) => {
    el.addEventListener("click", () => {
      const id = el.dataset.matchId;
      const pair = el.closest(".cmp-pair");
      pair.querySelectorAll(".cmp-hl").forEach((x) =>
        x.classList.toggle("cmp-active", x.dataset.matchId === id));
      const myCol = el.closest(".cmp-col");
      const other = [...pair.querySelectorAll(".cmp-col")].find((c) => c !== myCol);
      const target = other && other.querySelector(`[data-match-id="${CSS.escape(id)}"]`);
      if (target) target.scrollIntoView({ behavior: "smooth", block: "center" });
    });
  });
  applyCmpFilters();
}

